const TR_HORIZONS=[3,5,8];function trXPOver(player,n){if(typeof xpOver!="function"||typeof xpPlanGWs!="function")return null;const gws=xpPlanGWs(n);return!gws||!gws.length?null:{gws,xp:xpOver(player,gws)}}function trFixtures(teamId,n){const all=typeof teamFixtures6<"u"&&teamFixtures6[teamId]||[];return(typeof xpPlanGWs=="function"?xpPlanGWs(n):[]).map(gw=>{const matches=all.filter(f=>f.event===gw);if(!matches.length)return{gw,difficulty:null,opponent:null,isHome:null,blank:!0};const m=matches[0];return{gw,difficulty:m.difficulty||3,opponent:m.opponent,isHome:m.isHome,blank:!1,double:matches.length>1}})}function trAvgFdr(strip){const played=strip.filter(f=>!f.blank);return played.length?played.reduce((s,f)=>s+f.difficulty,0)/played.length:null}function trMinutes(player){const m=typeof expectedMinutesModel=="function"?expectedMinutesModel(player):null,pStart=m?m.pStart:null;let label="unknown";return pStart!=null&&(label=pStart>=.8?"nailed":pStart>=.6?"likely":"rotation risk"),{pStart,label,expMins:m?Math.round(m.expMins):null,status:player.status,news:player.news||"",flagged:player.status==="d"||player.status==="i"||player.status==="s"||player.status==="u"}}function trOwnershipBand(own){return own==null?"unknown":own>25?"template":own>=8?"mid":"differential"}function trSwing(teamId){const s=typeof fixtureSwingData<"u"&&fixtureSwingData[teamId]||null;return s?{direction:s.direction,from:s.currentFdr,to:s.futureFdr,gw:s.swingGW}:null}function trRationale(move,opts){if(!move||!move.out||!move.in)return null;const o=opts||{},out=move.out,inc=move.in,horizons=TR_HORIZONS.map(n=>{const a=trXPOver(out,n),b=trXPOver(inc,n);return!a||!b?{n,outXP:null,inXP:null,delta:null,gws:null}:{n,gws:a.gws,outXP:a.xp,inXP:b.xp,delta:Math.round((b.xp-a.xp)*10)/10}}).filter(h=>h.gws&&h.gws.length),outStrip=trFixtures(out.teamId,5),inStrip=trFixtures(inc.teamId,5),sellPrice=out.sellPrice!=null?out.sellPrice:out.price,bank=o.bank!=null?o.bank:0;return{out,in:inc,horizons,shape:(()=>{const h3=horizons.find(h=>h.n===3),h8=horizons.find(h=>h.n===8);if(!h3||!h8||h3.delta==null||h8.delta==null)return null;const rate3=h3.delta/h3.n,rate8=h8.delta/h8.n;return rate3>0?rate8<=rate3*.4?"fixture-run":rate8>rate3*1.6?"long-term-upgrade":"steady":rate8>rate3?"long-term-upgrade":rate8<rate3?"fixture-run":"steady"})(),fixtures:{out:{strip:outStrip,avgFdr:trAvgFdr(outStrip),swing:trSwing(out.teamId)},in:{strip:inStrip,avgFdr:trAvgFdr(inStrip),swing:trSwing(inc.teamId)}},money:{sellPrice,buyPrice:inc.price,bankAfter:Math.round((bank+sellPrice-inc.price)*10)/10,affordable:inc.price<=sellPrice+bank+.001,outPriceProgress:out.priceProgress||0,inPriceProgress:inc.priceProgress||0},risk:{out:trMinutes(out),in:trMinutes(inc)},ownership:{out:out.ownership,in:inc.ownership,delta:inc.ownership!=null&&out.ownership!=null?Math.round((inc.ownership-out.ownership)*10)/10:null,inBand:trOwnershipBand(inc.ownership),outBand:trOwnershipBand(out.ownership)},cost:o.hitCost||0}}function trStripHTML(strip){return strip.map(f=>f.blank?`<span class="tr-fx blank" data-tooltip="GW${f.gw} \u2014 no fixture">\u2014</span>`:`<span class="tr-fx fdr-${f.difficulty}${f.double?" dbl":""}"
                     data-tooltip="${escHTML(`GW${f.gw} \u2014 ${f.isHome?"home to":"away at"} ${f.opponent||"?"}, difficulty ${f.difficulty}`)}"
                   >${escHTML((f.opponent||"?").slice(0,3))}</span>`).join("")}function trSwingHTML(swing){if(!swing)return"";const better=swing.direction==="improving";return`<span class="tr-swing ${better?"up":"down"}"
                data-tooltip="${escHTML(`Average difficulty ${swing.from} over the next three, then ${swing.to} from GW${swing.gw}.`)}"
                >${better?"\u2191 eases":"\u2193 hardens"} GW${swing.gw}</span>`}function trRiskHTML(r,who){return r.flagged?`<span class="tr-risk bad" data-tooltip="${escHTML(r.news||"Carrying a fitness flag")}">flagged</span>`:`<span class="tr-risk ${r.label==="nailed"?"good":r.label==="likely"?"ok":"bad"}" data-tooltip="${escHTML(`${who} starts about ${Math.round((r.pStart||0)*100)}% of the time, averaging ${r.expMins}\u2032 when he does.`)}"
                >${escHTML(r.label)}</span>`}function trShapeNote(shape,h3,h8){const s=v=>(v>0?"+":"")+v;if(h3.delta<=0)return h8.delta>0?`It costs you ${Math.abs(h3.delta)} over the next three gameweeks and is ${s(h8.delta)} by eight \u2014 you are paying now for a player who is worth more later.`:h8.delta<h3.delta?`The gap widens against you across the horizon (${s(h3.delta)} at three, ${s(h8.delta)} at eight). The projection does not argue for this move on its own; it only makes sense as part of the set above.`:`Nothing to gain at either horizon (${s(h3.delta)} at three, ${s(h8.delta)} at eight). Whatever this move is for, it is not the projection.`;if(shape==="fixture-run")return`Most of it is in the next three gameweeks: ${s(h3.delta)} there, against ${s(h8.delta)} across all eight. That is a fixture play \u2014 good now, and worth revisiting once the run ends.`;if(shape==="long-term-upgrade")return`The edge builds: ${s(h3.delta)} over three gameweeks and ${s(h8.delta)} over eight, which is more per week later than it is now. That is an upgrade rather than a fixture play, so it does not need to pay off immediately.`;const rate=h3.delta/h3.n;return rate<.05?`Much the same either way (${s(h3.delta)} over three gameweeks, ${s(h8.delta)} over eight). The projection is close to neutral on this one.`:`Worth about ${rate.toFixed(1)} a gameweek throughout \u2014 ${s(h3.delta)} over three and ${s(h8.delta)} over eight. The gain is not resting on one kind run.`}function trRenderCard(rationale,opts){const r=rationale;if(!r)return"";const showHeader=!opts||opts.header!==!1,h=n=>r.horizons.find(x=>x.n===n),h3=h(3),h5=h(5),h8=h(8),sign=v=>(v>0?"+":"")+v.toFixed(1),cols=r.horizons.map(x=>`
                <div class="tr-h ${x.n===5?"lead":""}" data-tooltip="${escHTML(`${r.in.name} projects ${x.inXP.toFixed(1)} over the next ${x.n} gameweeks against ${r.out.name}'s ${x.outXP.toFixed(1)}.`)}">
                    <span class="tr-h-n">${x.n} GW</span>
                    <span class="tr-h-v ${x.delta>0?"up":x.delta<0?"down":""}">${sign(x.delta)}</span>
                </div>`).join(""),m=r.money,moneyLine=m.bankAfter>=0?`\xA3${m.sellPrice.toFixed(1)}m out, \xA3${m.buyPrice.toFixed(1)}m in \u2014 \xA3${m.bankAfter.toFixed(1)}m left in the bank.`:`\xA3${m.buyPrice.toFixed(1)}m is \xA3${Math.abs(m.bankAfter).toFixed(1)}m more than selling ${escHTML(r.out.name)} raises.`,own=r.ownership,swing=typeof eoSwing=="function"&&typeof eoReady=="function"&&eoReady()?eoSwing(r.out.id,r.in.id):null;let ownLine="";if(swing){const names=`${escHTML(r.in.name)} ${eoText(swing.in)}, ${escHTML(r.out.name)} ${eoText(swing.out)}`,field=`of the ${escHTML(swing.label.toLowerCase())}`;ownLine=Math.abs(swing.delta)<2?`Both carry about the same share ${field} (${names}), so this barely moves you against them.`:swing.delta>0?`${names} ${field} \u2014 taking on ${swing.delta}pp more of the field, which protects your rank in a good week and cannot gain you much.`:`${names} ${field} \u2014 shedding ${Math.abs(swing.delta)}pp of the field, so it gains rank when it comes off and loses rank when it does not.`}else if(own.delta!=null){const ownNames=`${escHTML(r.in.name)} ${own.in}%, ${escHTML(r.out.name)} ${own.out}%`;ownLine=Math.abs(own.delta)<1?`Owned by much the same share (${ownNames}), so this barely moves you against the field.`:own.delta>0?`${ownNames} \u2014 ${own.delta}pp more owned, which follows the field rather than trying to beat it.`:`${ownNames} \u2014 ${Math.abs(own.delta)}pp less owned, so it gains rank when it comes off and loses rank when it does not.`}return`<div class="tr-card">
                ${showHeader?`<div class="tr-move">
                    <span class="tr-out">${escHTML(r.out.name)}<small>${escHTML(r.out.team)} \xB7 \xA3${m.sellPrice.toFixed(1)}m</small></span>
                    <span class="tr-arrow">\u2192</span>
                    <span class="tr-in">${escHTML(r.in.name)}<small>${escHTML(r.in.team)} \xB7 \xA3${m.buyPrice.toFixed(1)}m</small></span>
                </div>`:""}

                <div class="tr-horizons" data-tooltip="Projected points gained over three, five and eight gameweeks. Five is the horizon the recommendation is decided on.">
                    ${cols}
                </div>
                ${h3&&h8?`<p class="tr-shape">${escHTML(trShapeNote(r.shape,h3,h8))}</p>`:""}

                <div class="tr-row">
                    <span class="tr-label">Fixtures</span>
                    <span class="tr-strips">
                        <span class="tr-side"><em>out</em>${trStripHTML(r.fixtures.out.strip)}${trSwingHTML(r.fixtures.out.swing)}</span>
                        <span class="tr-side"><em>in</em>${trStripHTML(r.fixtures.in.strip)}${trSwingHTML(r.fixtures.in.swing)}</span>
                    </span>
                </div>

                <div class="tr-row">
                    <span class="tr-label">Minutes</span>
                    <span class="tr-vals">${trRiskHTML(r.risk.out,r.out.name)} \u2192 ${trRiskHTML(r.risk.in,r.in.name)}</span>
                </div>

                <div class="tr-row">
                    <span class="tr-label">Money</span>
                    <span class="tr-vals ${m.affordable?"":"bad"}">${moneyLine}</span>
                </div>

                ${ownLine?`<div class="tr-row"><span class="tr-label">Ownership</span><span class="tr-vals">${ownLine}</span></div>`:""}
                ${r.cost?`<div class="tr-row"><span class="tr-label">Hit</span><span class="tr-vals bad">\u2212${r.cost} points, already deducted from the figures above.</span></div>`:""}
            </div>`}
